task apps_2992__switcheroo(s: seq) returns (r: seq)
  ensures len(r) == len(s)
  ensures forall i in [0, len(s)) . s[i] == 97 ==> r[i] == 98
  ensures forall i in [0, len(s)) . s[i] == 98 ==> r[i] == 97
  ensures forall i in [0, len(s)) . s[i] == 99 ==> r[i] == 99
{
  r := [];
  var i: int := 0;
  while i < len(s)
    invariant 0 <= i
    invariant i <= len(s)
    invariant len(r) == i
    invariant forall j in [0, len(r)) . s[j] == 97 ==> r[j] == 98
    invariant forall j in [0, len(r)) . s[j] == 98 ==> r[j] == 97
    invariant forall j in [0, len(r)) . s[j] == 99 ==> r[j] == 99
    decreases len(s) - i
  {
    if s[i] == 97 {
      r := r + [98];
    } else {
      if s[i] == 98 {
        r := r + [97];
      } else {
        r := r + [99];
      }
    }
    i := i + 1;
  }
}

